package com.aeroreserve.model;

import java.util.ArrayList;

/**
 * Booking is the central record that ties together:
 *   - a Flight
 *   - one or more Passengers
 *   - the specific Seats they chose
 *   - baggage option
 *   - total fare
 *   - payment details
 *   - booking status (CONFIRMED or CANCELLED)
 *
 * A unique bookingRef is generated by BookingService and stored here.
 * Booking objects are stored in a HashMap<String, Booking> keyed by bookingRef.
 */
public class Booking {

    // ── Nested enum ───────────────────────────────────────────────────────────

    /**
     * A booking is either active (CONFIRMED) or cancelled (CANCELLED).
     * When cancelled the seats are freed so other users can book them.
     */
    public enum BookingStatus {
        CONFIRMED,
        CANCELLED
    }

    // ── Fields ────────────────────────────────────────────────────────────────

    private String              bookingRef;   // e.g. "ARB-20250710-001"
    private Flight              flight;       // the flight this booking is for
    private ArrayList<Passenger> passengers;  // one Passenger per traveller
    private ArrayList<Seat>     seats;        // the actual Seat objects reserved
    private String              baggageOption; // e.g. "15 kg", "25 kg", "No Baggage"
    private double              totalFare;    // base fare × passengers + baggage + extras
    private BookingStatus       status;       // CONFIRMED or CANCELLED
    private Payment             payment;      // payment record (set after checkout)
    private String              customerEmail; // which customer made this booking

    // ── Constructor ───────────────────────────────────────────────────────────

    /**
     * Creates a new booking.  Status starts as CONFIRMED and payment is set later.
     *
     * @param bookingRef     the unique reference string
     * @param flight         the Flight being booked
     * @param passengers     list of Passenger objects
     * @param seats          list of chosen Seat objects
     * @param baggageOption  selected baggage allowance string
     * @param totalFare      total price in INR
     * @param customerEmail  email of the customer who made the booking
     */
    public Booking(String bookingRef, Flight flight,
                   ArrayList<Passenger> passengers, ArrayList<Seat> seats,
                   String baggageOption, double totalFare, String customerEmail) {
        this.bookingRef    = bookingRef;
        this.flight        = flight;
        this.passengers    = passengers;
        this.seats         = seats;
        this.baggageOption = baggageOption;
        this.totalFare     = totalFare;
        this.customerEmail = customerEmail;
        this.status        = BookingStatus.CONFIRMED; // new booking is always CONFIRMED
        this.payment       = null; // payment is attached after checkout
    }

    // ── Getters ───────────────────────────────────────────────────────────────

    /** Returns the unique booking reference code. */
    public String getBookingRef() { return bookingRef; }

    /** Returns the Flight associated with this booking. */
    public Flight getFlight() { return flight; }

    /** Returns the list of passengers on this booking. */
    public ArrayList<Passenger> getPassengers() { return passengers; }

    /** Returns the list of reserved Seat objects. */
    public ArrayList<Seat> getSeats() { return seats; }

    /** Returns the selected baggage option string. */
    public String getBaggageOption() { return baggageOption; }

    /** Returns the total fare charged in INR. */
    public double getTotalFare() { return totalFare; }

    /** Returns the current booking status (CONFIRMED or CANCELLED). */
    public BookingStatus getStatus() { return status; }

    /** Returns the Payment object for this booking (may be null before checkout). */
    public Payment getPayment() { return payment; }

    /** Returns the email of the customer who made this booking. */
    public String getCustomerEmail() { return customerEmail; }

    // ── Setters ───────────────────────────────────────────────────────────────

    /**
     * Changes the booking status.
     * Called by BookingService.cancelBooking() to set status to CANCELLED.
     *
     * @param status the new status
     */
    public void setStatus(BookingStatus status) {
        this.status = status;
    }

    /**
     * Attaches the payment record once the user completes checkout.
     *
     * @param payment the completed Payment object
     */
    public void setPayment(Payment payment) {
        this.payment = payment;
    }

    // ── Utility ──────────────────────────────────────────────────────────────

    /**
     * Returns a multi-line summary of this booking (used in the ticket file).
     */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Booking Ref : ").append(bookingRef).append("\n");
        sb.append("Flight      : ").append(flight.getFlightNo())
          .append(" | ").append(flight.getFrom()).append(" -> ").append(flight.getTo()).append("\n");
        sb.append("Date        : ").append(flight.getDate()).append("\n");
        sb.append("Departure   : ").append(flight.getDepartureTime())
          .append("  Arrival: ").append(flight.getArrivalTime()).append("\n");
        sb.append("Passengers  : ").append(passengers.size()).append("\n");

        // list each passenger
        for (int i = 0; i < passengers.size(); i++) {
            sb.append("  ").append(i + 1).append(". ").append(passengers.get(i)).append("\n");
        }

        // list seat numbers
        sb.append("Seats       : ");
        for (Seat s : seats) {
            sb.append(s.getSeatNo()).append(" ");
        }
        sb.append("\n");

        sb.append("Baggage     : ").append(baggageOption).append("\n");
        sb.append("Total Fare  : INR ").append(totalFare).append("\n");
        sb.append("Status      : ").append(status).append("\n");

        if (payment != null) {
            sb.append("Payment     : ").append(payment).append("\n");
        }
        return sb.toString();
    }
}

